package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// Creative arrangement uses structured note data, NOT an unconstrained AHK
// rewrite. AHK is generated by the tested local serializer after validation.
const (
	aiEditPreserve        = "preserve"
	aiEditCreative        = "creative"
	maxCreativeSongEvents = 2500
	creativeChunkSize     = 70
)

func normalizeAIEditMode(s string) string {
	if s == aiEditCreative {
		return aiEditCreative
	}
	return aiEditPreserve
}

// MIDI-origin sidecars contain no API keys or audio, only original extracted
// MIDI note-on events. They allow AI to see actual pitch data when available.
type lyreSourceBundle struct {
	Version       int          `json:"version"`
	SourceFile    string       `json:"source_file,omitempty"`
	StartMs       int64        `json:"start_ms"`
	PlaybackSpeed float64      `json:"playback_speed"`
	Transpose     int          `json:"transpose"`
	PianoNotes    []pianoEvent `json:"piano_notes,omitempty"`
}

func sourceSidecarPath(ahkPath string) string { return ahkPath + ".cazy-notes.json" }
func saveSourceSidecar(ahkPath, sourceFile string, score lyreScore) error {
	if len(score.SourcePiano) == 0 {
		return nil
	}
	notes := score.SourcePiano
	if len(notes) > 30000 {
		notes = notes[:30000]
	}
	speed := score.PlaybackSpeed
	if speed <= 0 {
		speed = 1
	}
	data, err := json.Marshal(lyreSourceBundle{Version: 1, SourceFile: sourceFile, StartMs: score.SourceStartMs, PlaybackSpeed: speed, Transpose: score.SemitoneShift, PianoNotes: notes})
	if err != nil {
		return err
	}
	return os.WriteFile(sourceSidecarPath(ahkPath), data, 0600)
}
func readSourceSidecar(path string) (lyreSourceBundle, error) {
	var bundle lyreSourceBundle
	b, err := os.ReadFile(sourceSidecarPath(path))
	if err != nil {
		return bundle, err
	}
	if len(b) > 4*1024*1024 {
		return bundle, errors.New("oversized music reference")
	}
	if err = json.Unmarshal(b, &bundle); err != nil {
		return bundle, err
	}
	if bundle.PlaybackSpeed <= 0 {
		bundle.PlaybackSpeed = 1
	}
	if len(bundle.PianoNotes) > 30000 {
		return bundle, errors.New("too many source notes")
	}
	return bundle, nil
}

var ahkNotePairRE = regexp.MustCompile(`(?i)\[\s*(\d+(?:\.\d+)?)\s*,\s*"([zxcvbnmasdfghjqwertyu]{1,21})"\s*\]`)

const lyreLetters = "zxcvbnmasdfghjqwertyu"

func parseAHKLyreScore(src string) (lyreScore, error) {
	_, blocks, _, err := protectLyreNotes(src)
	if err != nil {
		return lyreScore{}, err
	}
	if len(blocks) == 0 {
		return lyreScore{}, errors.New("selected AHK has no recognizable timestamped lyre note array (notes := [[milliseconds, \"keys\"]]). Select a Cazy Lyre-generated song")
	}
	notes := make([]lyreEvent, 0, 512)
	for _, b := range blocks {
		for _, m := range ahkNotePairRE.FindAllStringSubmatch(b.Original, -1) {
			ms, e := strconv.ParseFloat(m[1], 64)
			if e != nil || ms < 0 || ms > 4*3600000 {
				return lyreScore{}, errors.New("invalid note timestamp")
			}
			keys := strings.ToLower(m[2])
			notes = append(notes, lyreEvent{Ms: int64(math.Round(ms)), Keys: keys})
			if len(notes) > maxCreativeSongEvents {
				return lyreScore{}, fmt.Errorf("song has more than %d events; shorten the section before creative editing", maxCreativeSongEvents)
			}
		}
	}
	if len(notes) < 4 {
		return lyreScore{}, errors.New("not enough musical events to arrange")
	}
	sort.SliceStable(notes, func(i, j int) bool { return notes[i].Ms < notes[j].Ms })
	first := notes[0].Ms
	for i := range notes {
		notes[i].Ms -= first
	}
	return lyreScore{Quality: qualityFull, Events: notes, Notes: len(notes), DurationMs: notes[len(notes)-1].Ms, PlaybackSpeed: 1}, nil
}

type creativeJSONEvent struct {
	Ms   int64  `json:"ms"`
	Keys string `json:"keys"`
}
type creativeJSONResponse struct {
	Events []creativeJSONEvent `json:"events"`
	Notes  string              `json:"notes,omitempty"`
}

// normalizeCreativeChord tolerates the way AI sometimes formats the same
// valid lyre keys ("A + S", "[a,s]"). It NEVER guesses a key from an
// unsupported pitch or unknown text; those require source-note recovery.
func normalizeCreativeChord(raw string) (string, error) {
	raw = strings.ToLower(strings.TrimSpace(raw))
	seen := make(map[rune]bool, 6)
	var chord strings.Builder
	for _, k := range raw {
		switch k {
		case ' ', '\t', '\n', '\r', '+', ',', '|', '[', ']', '(', ')':
			continue
		default:
			if !strings.ContainsRune(lyreLetters, k) {
				return "", fmt.Errorf("invalid Genshin lyre key %q", k)
			}
			if !seen[k] {
				seen[k] = true
				chord.WriteRune(k)
			}
		}
	}
	if chord.Len() == 0 {
		return "", errors.New("AI returned an empty chord")
	}
	if chord.Len() > 6 {
		return "", errors.New("AI returned a chord with more than 6 notes")
	}
	return chord.String(), nil
}

// sourceChordNear returns the closest unmodified source chord only when the
// timing matches reasonably closely. This avoids inventing musical pitches
// when an AI note has an unsupported or blank key.
func sourceChordNear(original []lyreEvent, t int64) (string, bool) {
	const maxDifferenceMs int64 = 220
	closest := maxDifferenceMs + 1
	result := ""
	if len(original) == 0 {
		return "", false
	}
	offset := original[0].Ms
	for _, e := range original {
		distance := (e.Ms - offset) - t
		if distance < 0 {
			distance = -distance
		}
		if distance < closest {
			closest, result = distance, e.Keys
		}
	}
	return result, closest <= maxDifferenceMs && result != ""
}

// parseCreativeEventsWithRepairs returns a valid section plus the count of
// individual malformed AI chords recovered from the original transcription.
// If corruption exceeds the small repair budget, caller can retain the entire
// original section instead. No invalid chord ever reaches AHK generation.
func parseCreativeEventsWithRepairs(response string, original []lyreEvent, spanMs int64) ([]lyreEvent, int, error) {
	clean := strings.TrimSpace(stripCreativeCodeFence(response))
	var decoded creativeJSONResponse
	if err := json.Unmarshal([]byte(clean), &decoded); err != nil {
		return nil, 0, fmt.Errorf("AI returned invalid note JSON: %w", err)
	}
	if len(decoded.Events) < maxCreativeInt(3, len(original)/4) {
		return nil, 0, errors.New("AI removed too many musical events; rejected to prevent a silent arrangement")
	}
	if len(decoded.Events) > len(original)*3+12 {
		return nil, 0, errors.New("AI created too many notes; rejected to prevent noisy playback")
	}
	out := make([]lyreEvent, 0, len(decoded.Events))
	maxTime := spanMs + 450
	if maxTime < 1000 {
		maxTime = 1000
	}
	repaired := 0
	repairLimit := maxCreativeInt(2, len(decoded.Events)/12)
	for _, n := range decoded.Events {
		if n.Ms < 0 || n.Ms > maxTime {
			return nil, repaired, fmt.Errorf("AI moved note outside its music section: %dms", n.Ms)
		}
		chord, err := normalizeCreativeChord(n.Keys)
		if err != nil {
			originalChord, ok := sourceChordNear(original, n.Ms)
			if !ok {
				return nil, repaired, fmt.Errorf("%w (no matching source note to restore)", err)
			}
			chord = originalChord
			repaired++
			if repaired > repairLimit {
				return nil, repaired, fmt.Errorf("too many malformed AI chords (%d); source section must be retained", repaired)
			}
		}
		out = append(out, lyreEvent{Ms: n.Ms, Keys: chord})
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].Ms < out[j].Ms })
	unique := make([]lyreEvent, 0, len(out))
	for _, n := range out {
		if len(unique) > 0 && unique[len(unique)-1].Keys == n.Keys && n.Ms-unique[len(unique)-1].Ms < 18 {
			continue
		}
		unique = append(unique, n)
	}
	if len(unique) < maxCreativeInt(3, len(original)/4) {
		return nil, repaired, errors.New("too few valid notes after cleanup")
	}
	return unique, repaired, nil
}

func parseCreativeEvents(response string, original []lyreEvent, spanMs int64) ([]lyreEvent, error) {
	result, _, err := parseCreativeEventsWithRepairs(response, original, spanMs)
	return result, err
}

// chooseCreativeSection gracefully preserves the original transcription when
// an AI section cannot be validated. Each returned event is section-relative.
// This ensures malformed AI output never creates a silent or partial song.
func chooseCreativeSection(text string, original []lyreEvent, spanMs int64) ([]lyreEvent, int, bool, string) {
	edits, repaired, err := parseCreativeEventsWithRepairs(text, original, spanMs)
	if err == nil {
		return edits, repaired, false, ""
	}
	if len(original) == 0 {
		return nil, 0, true, err.Error()
	}
	fallback := make([]lyreEvent, len(original))
	for i, e := range original {
		fallback[i] = lyreEvent{Ms: e.Ms - original[0].Ms, Keys: e.Keys}
	}
	return fallback, 0, true, err.Error()
}

func chunkCreativeScore(events []lyreEvent, chunkSize int) [][]lyreEvent {
	if chunkSize < 5 {
		chunkSize = 5
	}
	var batches [][]lyreEvent
	for i := 0; i < len(events); i += chunkSize {
		j := i + chunkSize
		if j > len(events) {
			j = len(events)
		}
		batches = append(batches, events[i:j])
	}
	return batches
}
func originalPitchReference(bundle lyreSourceBundle, chunk []lyreEvent) []creativeJSONEvent {
	if len(chunk) == 0 || len(bundle.PianoNotes) == 0 {
		return nil
	}
	start := float64(bundle.StartMs) + float64(chunk[0].Ms)*bundle.PlaybackSpeed
	end := float64(bundle.StartMs) + float64(chunk[len(chunk)-1].Ms+400)*bundle.PlaybackSpeed
	refs := make([]creativeJSONEvent, 0, 140)
	for _, n := range bundle.PianoNotes {
		if float64(n.Ms) < start || float64(n.Ms) > end {
			continue
		}
		refs = append(refs, creativeJSONEvent{Ms: int64(math.Round((float64(n.Ms) - start) / bundle.PlaybackSpeed)), Keys: fmt.Sprint(n.Pitch)})
		if len(refs) >= 160 {
			break
		}
	}
	return refs
}

func maxCreativeInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// Keep core note validation testable on non-Windows platforms.
func stripCreativeCodeFence(s string) string {
	s = strings.TrimSpace(s)
	if !strings.HasPrefix(s, "```") {
		return s
	}
	first := strings.IndexByte(s, '\n')
	last := strings.LastIndex(s, "```")
	if first >= 0 && last > first {
		return strings.TrimSpace(s[first+1 : last])
	}
	return s
}
